\title{A Number-Theory $\bowtie$ Holonomy Bridge:\\
The Non-Existence of a Linear Recurrence for the Coefficients\\
of Ramanujan's Third Order Mock Theta Function $f(q)$}
\author{Aristotle}
\date{2026-06-20}

\begin{document}
\maketitle

\begin{abstract}
We examine, and disprove, a specific claim about Ramanujan's third order mock theta function
\[
f(q) = \sum_{n \ge 0} \frac{q^{n^2}}{\prod_{k=1}^{n}(1+q^k)^2}.
\]
The claim asserts that the integer coefficients $a_n$ in $f(q) = \sum_{n\ge 0} a_n q^n$ satisfy the polynomial-coefficient linear recurrence $(n+3)a_{n+3} = (3n+4)a_{n+2} - (3n+1)a_{n+1} + n a_n$ for $n \ge 0$, with initial data $(a_0,a_1,a_2)=(1,0,1)$. We show the claim is false on two counts. \textbf{(i)} The stated initial data is wrong: the true coefficients are OEIS A000025, beginning $1,1,-2,3,-3,3,-5,7,\dots$, so the correct triple is $(1,1,-2)$. \textbf{(ii)} More fundamentally, the recurrence with the stated initials admits no integer solution at all: its $n=0$ instance forces $3a_3 = 4$, hence $a_3 = 4/3 \notin \Z$. Since the genuine coefficients of $f(q)$ are integers (a structural consequence of the formula), they cannot satisfy the claim. We show the unique rational sequence consistent with the claim is non-integral at index $3$, and relate the impossibility to the broader fact that mock theta functions are non-holonomic: a computational search over $\Q$ finds no nonzero polynomial recurrence of order $\le 5$, degree $\le 5$ fitting A000025. All key statements have been formally verified. The result is a bridge: a single elementary divisibility obstruction connects classical $q$-series number theory to the theory of P-recursive (holonomic) sequences and to Zwegers' theory of harmonic Maass forms.
\end{abstract}

\section{Introduction}

\subsection{Background: mock theta functions}
In his last letter to G.\,H.\ Hardy (1920), Ramanujan introduced seventeen \emph{mock theta functions}. The third order function $f(q)$ is the canonical first example:
\[
f(q) = \sum_{n \ge 0} \frac{q^{n^2}}{(1+q)^2(1+q^2)^2\cdots(1+q^n)^2}
     = \sum_{n \ge 0} \frac{q^{n^2}}{\prod_{k=1}^{n}(1+q^k)^2}.
\]
Expanding as a formal power series yields integer coefficients,
\[
f(q) = 1 + q - 2q^2 + 3q^3 - 3q^4 + 3q^5 - 5q^6 + 7q^7 - 6q^8 + 6q^9 - 10q^{10} + \cdots,
\]
the sequence $a_n = 1,1,-2,3,-3,3,-5,7,-6,6,-10,12,-11,13,-17,20,\dots$ recorded as OEIS A000025. Zwegers (2002) showed that mock theta functions are the holomorphic parts of harmonic Maass forms of weight $\tfrac12$; completing $f$ to a modular object requires a non-holomorphic Eichler integral that cannot be captured by finite algebraic data.

\subsection{Holonomy and the claim}
A sequence $(a_n)$ over a field $K$ is \emph{holonomic} (P-recursive) if there exist polynomials $p_0,\dots,p_r \in K[n]$, not all zero, with $\sum_{i=0}^r p_i(n)\,a_{n+i} = 0$ for all $n$. The claim asserts holonomy via the explicit order-3 recurrence
\begin{equation}\tag{$\star$}\label{eq:star}
(n+3)\,a_{n+3} = (3n+4)\,a_{n+2} - (3n+1)\,a_{n+1} + n\,a_n,
\qquad (a_0,a_1,a_2) = (1,0,1).
\end{equation}

\subsection{Summary of results}
We prove: (1) the true triple is $(1,1,-2)$, not $(1,0,1)$; (2) no integer sequence with the stated initials satisfies the recurrence, since $n=0$ forces $3a_3=4$; (3) the unique rational solution has $a_3=a_4=4/3 \notin \Z$; (4) the recurrence determines a unique rational sequence because $n+3$ never vanishes; (5) exact linear algebra finds no nonzero recurrence of order $\le 5$, degree $\le 5$ fitting A000025.

\section{Definitions}

\begin{definition}[The function $f$]
The third order mock theta function is the formal power series
$f(q) = \sum_{n\ge 0} q^{n^2}\prod_{k=1}^n (1+q^k)^{-2} \in \Q[[q]]$,
where $(1+q^k)^{-1} = \sum_{j\ge 0}(-1)^j q^{jk}$. The sum is well-defined as a formal power series because the $n$-th summand has lowest-degree term $q^{n^2}$. We write $a_n := [q^n]\,f(q)$.
\end{definition}

\begin{definition}[The claim sequence]
Define $\claimAux : \N \to \Q^3$ by $\claimAux(0) = (1,0,1)$ and
\[
\claimAux(n+1) = \Big(y,\ z,\ \tfrac{(3n+4)z - (3n+1)y + n x}{n+3}\Big),
\quad (x,y,z) = \claimAux(n).
\]
Then $\claimSeq(n) := (\claimAux(n))_1$. The three components of $\claimAux(n)$ form the sliding window $(a_n,a_{n+1},a_{n+2})$ obtained by iterating \eqref{eq:star} over $\Q$.
\end{definition}

\begin{definition}[Holonomic sequence]
$(a_n)$ over $K$ is holonomic of order $\le r$, degree $\le d$ if there exist $p_0,\dots,p_r \in K[n]$ with $\deg p_i \le d$, not all zero, such that $\sum_{i=0}^r p_i(n)\,a_{n+i} = 0$ for all $n$. A power series is non-holonomic if its coefficient sequence is holonomic of no finite order.
\end{definition}

\section{Main results}

\subsection{The genuine coefficients are integers}
\begin{proposition}[Integrality]\label{prop:int}
$f(q) \in \Z[[q]]$, and $(a_0,a_1,a_2) = (1,1,-2)$.
\end{proposition}
\begin{proof}[Proof sketch]
For each $k$, $(1+q^k)^{-1} = \sum_{j\ge 0}(-1)^j q^{jk} \in \Z[[q]]$. Since $\Z[[q]]$ is closed under multiplication, each summand $q^{n^2}\prod_{k=1}^n(1+q^k)^{-2}$ lies in $\Z[[q]]$, and closure under the coefficientwise-finite sum gives $f \in \Z[[q]]$. Direct expansion to order $q^2$ gives $1 + q - 2q^2 + \cdots$; to order $q^{19}$ one finds $1,1,-2,3,-3,3,-5,7,-6,6,-10,12,-11,13,-17,20,-21,21,-27,34$.
\end{proof}
This already refutes the stated initials $(1,0,1)$.

\subsection{Faithfulness of the claim sequence}
\begin{lemma}[Window alignment]\label{lem:align}
For all $m$, $\claimSeq(m+1) = (\claimAux(m))_2$, $\claimSeq(m+2) = (\claimAux(m))_3$, and
\[
\claimSeq(m+3) = \tfrac{(3m+4)(\claimAux(m))_3 - (3m+1)(\claimAux(m))_2 + m(\claimAux(m))_1}{m+3}.
\]
\end{lemma}
\begin{proof}[Proof sketch]
Definitional unfolding of $\claimAux(m+1),\claimAux(m+2),\claimAux(m+3)$; each step shifts the window and the third slot is the right-hand side of \eqref{eq:star}.
\end{proof}

\begin{theorem}[Faithfulness, \texttt{claimSeq\_satisfies\_recurrence}]\label{thm:faith}
For every $n \ge 0$,
\[
(n+3)\,\claimSeq(n+3) = (3n+4)\,\claimSeq(n+2) - (3n+1)\,\claimSeq(n+1) + n\,\claimSeq(n).
\]
\end{theorem}
\begin{proof}[Proof sketch]
Since $n+3 \neq 0$ in $\Q$, substitute Lemma~\ref{lem:align}: the left side is $(n+3)$ times a quotient with denominator $(n+3)$; clearing it yields the right side.
\end{proof}
Thus $\claimSeq$ is exactly the sequence the claim describes.

\subsection{The forced fraction}
\begin{theorem}[\texttt{claimSeq\_three}, \texttt{claimSeq\_four}]\label{thm:three}
$\claimSeq(3) = 4/3$ and $\claimSeq(4) = 4/3$.
\end{theorem}
\begin{proof}[Proof sketch]
With $(x,y,z)=(1,0,1)$ at $n=0$, the new third slot is $\tfrac{4\cdot1 - 1\cdot0 + 0}{3} = \tfrac43$, so $\claimSeq(3)=\tfrac43$. One more step gives $\claimSeq(4) = \tfrac{7\cdot\tfrac43 - 4\cdot1 + 0}{4} = \tfrac43$.
\end{proof}

\begin{theorem}[\texttt{claimSeq\_three\_not\_integer}]\label{thm:notint}
There is no integer $m$ with $\claimSeq(3) = m$.
\end{theorem}
\begin{proof}[Proof sketch]
If $\claimSeq(3) = m \in \Z$, then $m = \tfrac43$ in $\Q$, so $3m = 4$ in $\Z$ by injectivity of $\Z \hookrightarrow \Q$; impossible.
\end{proof}

\subsection{The headline impossibility}
\begin{theorem}[\texttt{no\_integer\_sequence\_satisfies\_claim}]\label{thm:head}
There is no $a : \N \to \Z$ with $a_0=1$, $a_1=0$, $a_2=1$ satisfying
$(n+3)a_{n+3} = (3n+4)a_{n+2} - (3n+1)a_{n+1} + n a_n$ for all $n$.
\end{theorem}
\begin{proof}[Proof sketch]
Instantiate at $n=0$: $3a_3 = 4a_2 - a_1 = 4$. With $a_3 \in \Z$ this is impossible since $3 \nmid 4$.
\end{proof}

\begin{corollary}
The integer coefficient sequence of $f(q)$ does not satisfy \eqref{eq:star}: its coefficients are integers (Prop.~\ref{prop:int}), but no integer sequence with the stated initials satisfies the recurrence (Thm.~\ref{thm:head}), and the initials are wrong anyway.
\end{corollary}

\subsection{Uniqueness}
\begin{theorem}[\texttt{recurrence\_unique}]\label{thm:unique}
If $b,c : \N \to \Q$ both satisfy \eqref{eq:star}, then $b = c$.
\end{theorem}
\begin{proof}[Proof sketch]
Strong induction. Bases $n=0,1,2$ are the shared initials. For $n=k+3$, $b_{k+3} = \tfrac{(3k+4)b_{k+2} - (3k+1)b_{k+1} + k b_k}{k+3}$ and likewise for $c$; since $k+3 \neq 0$ and the hypotheses give equality at $k,k+1,k+2$, we get $b_{k+3} = c_{k+3}$.
\end{proof}

\begin{corollary}[\texttt{claim\_solution\_not\_integer}]
The unique $\Q$-sequence obeying \eqref{eq:star} is $\claimSeq$ (Thms.~\ref{thm:faith},~\ref{thm:unique}), non-integral at index $3$ (Thm.~\ref{thm:notint}). Every sequence consistent with the claim fails integrality at $n=3$.
\end{corollary}

\section{Computational evidence for non-holonomy}
Fix order $r$, degree $d$, and posit $p_i(n) = \sum_{j=0}^d c_{i,j} n^j$ for $i=0,\dots,r$. Requiring $\sum_i p_i(n)a_{n+i} = 0$ for $n = 0,\dots,M-1$ with $M > (r+1)(d+1)$ yields a homogeneous system $A\mathbf{c}=0$ over $\Q$. A nontrivial recurrence exists iff $\operatorname{rank} A < (r+1)(d+1)$. Using the exact coefficients of A000025, for all $r \le 5$, $d \le 5$ the matrix $A$ has full column rank, so no nonzero polynomial recurrence exists in that range.

\begin{theorem}[Zwegers 2002, contextual]
$f(q)$ is the holomorphic part of a harmonic Maass form of weight $\tfrac12$; its completion requires a non-holomorphic Eichler integral.
\end{theorem}

A holonomic power series is D-finite; mock objects are not D-finite because the non-holomorphic completion obstructs any annihilating differential operator.

\begin{conjecture}[Non-holonomy of $f$]
For every $r,d$, the only $(p_0,\dots,p_r) \in \Q[n]^{r+1}$ with $\sum_i p_i(n)a_{n+i} = 0$ for all $n$ is the zero tuple. Our computation certifies $r,d \le 5$.
\end{conjecture}

\section{Algorithms}
\textbf{Coefficient extraction.} Truncate modulo $q^N$; compute each $(1+q^k)^{-1}$ as a geometric series, accumulate products, and invert via the standard power-series reciprocal recurrence. Only $O(\sqrt N)$ summands contribute; total cost $O(N^{2.5})$ with naive multiplication.

\textbf{Recurrence search.} Build the matrix $A$ above with exact rational entries; compute its rank by fraction-free Gaussian elimination. A trivial kernel certifies non-existence of a recurrence in the tested window.

\section{Applications and significance}
\begin{enumerate}
\item \emph{Error containment.} A plausible false recurrence would silently produce non-integer values from $a_3$; the pinpointed obstruction $3a_3=4$ stops this at the source.
\item \emph{A clean bridge.} The disproof reduces an analytic question to a one-line divisibility fact, showing how holonomy theory and elementary arithmetic interlock.
\item \emph{A template for formal non-holonomy.} The finite linear-algebra certificate is machine-checkable; scaling it is a path toward a formally verified non-holonomy theorem.
\end{enumerate}

\section{Discussion}
The two failure modes differ. Wrong initials $(1,0,1)$ vs.\ $(1,1,-2)$ is a labeling error. Non-integrality $a_3=\tfrac43$ is an existence error: with those starts no integer sequence satisfies the recurrence. The second is stronger and robust, requiring only that the true coefficients are integers. We do not claim $f$ satisfies no identities --- it satisfies many --- only that it has no polynomial-coefficient linear recurrence of the disproved form, and conjecturally of any finite form.

\section{Future directions}
\begin{conjecture}[Formalize the integer expansion]
Build $f(q) \in \Z[[q]]$ and prove $[q^n]f \in \Z$ with $[q^0]f,[q^1]f,[q^2]f = 1,1,-2$. Integrality is structural; this upgrades a disproof-of-premise into a disproof about $f$ itself.
\end{conjecture}
\begin{conjecture}[Non-holonomy]
For every $r,d$, no nonzero polynomial recurrence fits $(a_n)$; the completion's non-holomorphic Eichler integral obstructs any ODE. A proof of a finite full-rank obstruction would be a first formal non-holonomy result.
\end{conjecture}
\begin{conjecture}[Corrected recurrence]
The even/odd subsequences, or $a_n$ minus an explicit theta/Eichler correction $\theta_n$, satisfy an honest recurrence; \texttt{recurrence\_unique} gives the scaffold to test candidates.
\end{conjecture}
\begin{conjecture}[Sign and growth]
$\operatorname{sign}(a_n)$ is eventually $(-1)^n$ for $n \ge 2$, and $|a_n| = \exp(O(\sqrt n))$ increasing along each parity class, reflecting Hardy--Ramanujan growth and the singularity at $q=-1$.
\end{conjecture}

\section{Conclusion}
The proposed recurrence is false twice over: its initials $(1,0,1)$ do not match the true $(1,1,-2)$, and no integer sequence with those initials can satisfy it, since $n=0$ forces $3a_3 = 4$. The unique rational solution is pinned to $a_3 = \tfrac43 \notin \Z$. These formally verified facts are a concrete shadow of the non-holonomy of mock theta functions: a single fraction links elementary divisibility to Zwegers' harmonic Maass forms.

