from fractions import Fraction
from typing import List

def poly_mul(a: List[Fraction], b: List[Fraction], N: int) -> List[Fraction]:
    r = [Fraction(0)] * N
    for i, ai in enumerate(a):
        if ai == 0:
            continue
        for j, bj in enumerate(b):
            if i + j < N and bj != 0:
                r[i + j] += ai * bj
    return r

def poly_inv(a: List[Fraction], N: int) -> List[Fraction]:
    r = [Fraction(0)] * N
    r[0] = 1 / a[0]
    for n in range(1, N):
        s = Fraction(0)
        for k in range(1, n + 1):
            ak = a[k] if k < len(a) else Fraction(0)
            s += ak * r[n - k]
        r[n] = -s / a[0]
    return r

def f_coefficients(N: int) -> List[int]:
    f = [Fraction(0)] * N
    n = 0
    while n * n < N:
        term = [Fraction(0)] * N
        term[n * n] = Fraction(1)
        denom = [Fraction(0)] * N
        denom[0] = Fraction(1)
        for k in range(1, n + 1):
            factor = [Fraction(0)] * N
            factor[0] = Fraction(1)
            if k < N:
                factor[k] = Fraction(1)
            denom = poly_mul(denom, factor, N)
            denom = poly_mul(denom, factor, N)
        term = poly_mul(term, poly_inv(denom, N), N)
        f = [f[i] + term[i] for i in range(N)]
        n += 1
    return [int(c) for c in f]

if __name__ == "__main__":
    print(f_coefficients(20))
    # [1, 1, -2, 3, -3, 3, -5, 7, -6, 6, -10, 12, -11, 13, -17, 20, -21, 21, -27, 34]

