from fractions import Fraction
from typing import List

def poly_mul(a: List[Fraction], b: List[Fraction], N: int) -> List[Fraction]:
    r = [Fraction(0)] * N
    for i, ai in enumerate(a):
        if ai == 0:
            continue
        for j, bj in enumerate(b):
            if i + j < N and bj != 0:
                r[i + j] += ai * bj
    return r

def poly_inv(a: List[Fraction], N: int) -> List[Fraction]:
    """Reciprocal of a power series with invertible constant term, mod q^N."""
    r = [Fraction(0)] * N
    r[0] = 1 / a[0]
    for n in range(1, N):
        s = sum((a[k] if k < len(a) else Fraction(0)) * r[n - k]
                for k in range(1, n + 1))
        r[n] = -s / a[0]
    return r

def f_coefficients(N: int) -> List[int]:
    """Coefficients of f(q) = sum_n q^{n^2} / prod_{k=1}^n (1+q^k)^2, mod q^N."""
    f = [Fraction(0)] * N
    n = 0
    while n * n < N:
        term = [Fraction(0)] * N
        term[n * n] = Fraction(1)
        denom = [Fraction(0)] * N
        denom[0] = Fraction(1)
        for k in range(1, n + 1):
            factor = [Fraction(0)] * N
            factor[0] = Fraction(1)
            if k < N:
                factor[k] = Fraction(1)
            denom = poly_mul(poly_mul(denom, factor, N), factor, N)
        term = poly_mul(term, poly_inv(denom, N), N)
        f = [f[i] + term[i] for i in range(N)]
        n += 1
    return [int(c) for c in f]

from fractions import Fraction
from typing import List

def rank_exact(rows: List[List[Fraction]]) -> int:
    """Rank of a rational matrix via fraction-free Gaussian elimination."""
    mat = [row[:] for row in rows]
    if not mat:
        return 0
    ncols = len(mat[0])
    rank = 0
    pivot_row = 0
    for col in range(ncols):
        piv = next((r for r in range(pivot_row, len(mat)) if mat[r][col] != 0), None)
        if piv is None:
            continue
        mat[pivot_row], mat[piv] = mat[piv], mat[pivot_row]
        pv = mat[pivot_row][col]
        for r in range(len(mat)):
            if r != pivot_row and mat[r][col] != 0:
                f = mat[r][col] / pv
                mat[r] = [mat[r][c] - f * mat[pivot_row][c] for c in range(ncols)]
        rank += 1
        pivot_row += 1
        if pivot_row == len(mat):
            break
    return rank

def recurrence_exists(a: List[int], order: int, degree: int) -> bool:
    """True iff a nonzero recurrence sum_i p_i(n) a_{n+i}=0, deg p_i<=degree, exists."""
    nunknown = (order + 1) * (degree + 1)
    max_n = len(a) - order
    if max_n <= nunknown:
        raise ValueError("supply more coefficients to certify")
    rows: List[List[Fraction]] = []
    for n in range(max_n):
        row: List[Fraction] = []
        for i in range(order + 1):
            for j in range(degree + 1):
                row.append(Fraction(a[n + i]) * Fraction(n) ** j)
        rows.append(row)
    return rank_exact(rows) < nunknown
